import { GoogleGenAI, GenerateContentResponse, Type, FunctionDeclaration } from "@google/genai";
import { AppMode, MessageRole } from "../types";
import { jokeTool, weatherTool, learningTool, codeGeneratorTool, toolHandlers } from "./tools";

export class GeminiService {
  private getClient() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async sendMessage(
    message: string, 
    history: any[] = [], 
    mode: AppMode = AppMode.GENERAL
  ) {
    const ai = this.getClient();

    // Choose model based on task complexity
    // gemini-3-pro-preview for learning and dev (complex reasoning)
    // gemini-3-flash-preview for general and news (speed)
    const model = (mode === AppMode.LEARNING || mode === AppMode.DEVELOPER) 
      ? 'gemini-3-pro-preview' 
      : 'gemini-3-flash-preview';

    // Guideline: Search is mutual exclusive with other tools in most configurations
    const tools: any[] = [];
    if (mode === AppMode.NEWS || mode === AppMode.LEARNING) {
      tools.push({ googleSearch: {} });
    } else {
      tools.push({
        functionDeclarations: [jokeTool, weatherTool, learningTool, codeGeneratorTool]
      });
    }

    const systemInstruction = `You are AI Nexus, a world-class AI companion.
    Current Operative Mode: ${mode}

    GUIDELINES:
    1. NEWS Mode: Provide concise, factual global news briefings using Google Search.
    2. LEARNING Mode: Act as an expert AI/ML tutor. Break down complex topics into digestible parts.
    3. DEVELOPER Mode: Demonstrate "Function Calling" capabilities. Show thought processes.
    4. HUMOR: Always ready to crack a joke using the get_random_joke tool when asked.
    5. TRANSPARENCY: Mention when you are using tools or searching the web to enhance your answer.
    6. ACCURACY: If using Google Search, prioritize verified news sources.

    Note: Your API Key is handled securely via the environment. Do not mention it.`;

    try {
      const response = await ai.models.generateContent({
        model: model,
        contents: [...history, { role: 'user', parts: [{ text: message }] }],
        config: {
          systemInstruction,
          tools,
          // Only enable thinking for the Pro model or Developer mode
          thinkingConfig: { 
            thinkingBudget: (mode === AppMode.DEVELOPER || model === 'gemini-3-pro-preview') ? 2000 : 0 
          }
        },
      });

      const candidate = response.candidates?.[0];
      const functionCalls = response.functionCalls;

      // Extract grounding links correctly from groundingMetadata
      const groundingLinks = candidate?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) || [];

      // Handle Function Calls
      if (functionCalls && functionCalls.length > 0) {
        const toolResponses = await Promise.all(
          functionCalls.map(async (fc) => {
            const handler = toolHandlers[fc.name];
            try {
              const result = handler ? await handler(fc.args) : { error: `Tool ${fc.name} not found` };
              return {
                id: fc.id,
                name: fc.name,
                response: result
              };
            } catch (err) {
              return { id: fc.id, name: fc.name, response: { error: "Execution failed" } };
            }
          })
        );

        // Send tool results back to the model for the final response
        const finalResponse = await ai.models.generateContent({
          model: model,
          contents: [
            ...history,
            { role: 'user', parts: [{ text: message }] },
            { role: 'model', parts: functionCalls.map(fc => ({ functionCall: fc })) },
            { role: 'tool', parts: toolResponses.map(tr => ({ functionResponse: tr })) }
          ],
          config: { systemInstruction, tools }
        });

        return {
          text: finalResponse.text,
          functionCalls,
          toolResponses,
          groundingLinks
        };
      }

      // Extract thinking if available in parts
      const thinkingPart = candidate?.content?.parts?.find((p: any) => 'thought' in p);

      return {
        text: response.text || "I processed that, but have no text response.",
        groundingLinks,
        thinking: (thinkingPart as any)?.thought
      };

    } catch (error: any) {
      console.error("Gemini API Error Details:", error);
      // Graceful error reporting
      if (error?.message?.includes("API_KEY")) {
        throw new Error("System API Key configuration issue. Please ensure the environment is ready.");
      }
      throw error;
    }
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, MessageRole, AppMode } from '../types';
import { Icons } from '../constants';

interface ChatInterfaceProps {
  messages: ChatMessage[];
  onSend: (text: string) => void;
  isLoading: boolean;
  mode: AppMode;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onSend, isLoading, mode }) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isLoading) {
      onSend(input);
      setInput('');
    }
  };

  const getModeColor = (m: AppMode) => {
    switch (m) {
      case AppMode.NEWS: return 'text-amber-400 bg-amber-400/10 border-amber-400/20';
      case AppMode.LEARNING: return 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
      case AppMode.DEVELOPER: return 'text-purple-400 bg-purple-400/10 border-purple-400/20';
      default: return 'text-indigo-400 bg-indigo-400/10 border-indigo-400/20';
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-x border-slate-800 shadow-2xl overflow-hidden relative">
      {/* Header */}
      <div className="p-4 border-b border-slate-800 bg-slate-900/80 backdrop-blur-xl flex justify-between items-center sticky top-0 z-20">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl shadow-lg shadow-indigo-500/20">
            <Icons.Robot />
          </div>
          <div>
            <h1 className="font-bold text-lg tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">AI Nexus</h1>
            <div className="flex items-center gap-2">
              <span className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-indigo-500 animate-ping' : 'bg-green-500'}`} />
              <span className={`text-[10px] font-bold uppercase tracking-widest border px-2 py-0.5 rounded ${getModeColor(mode)}`}>
                {mode}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-slate-950"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-6 text-center px-8">
            <div className="p-6 bg-slate-900/50 rounded-full border border-slate-800 animate-pulse">
               <Icons.Robot />
            </div>
            <div className="max-w-md">
              <p className="text-xl font-bold text-slate-200 mb-2">Initialize Connection</p>
              <p className="text-sm leading-relaxed text-slate-400">
                Current Mode: <span className="font-mono text-indigo-400">{mode.toUpperCase()}</span>.
                I'm ready to assist with global briefings, ML tutorials, or system tool testing.
              </p>
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
          >
            <div className={`max-w-[88%] rounded-2xl p-4 shadow-xl border ${
              msg.role === MessageRole.USER 
                ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                : 'bg-slate-800/90 backdrop-blur-sm text-slate-100 border-slate-700/50 rounded-tl-none'
            }`}>
              {/* Thinking Segment */}
              {msg.thinking && (
                <div className="mb-4 p-3 bg-black/40 rounded-xl border border-slate-700/50 text-[11px] text-slate-300 font-mono overflow-hidden">
                  <div className="flex items-center gap-2 mb-2 text-indigo-400 border-b border-slate-800 pb-1">
                    <Icons.Terminal />
                    <span className="uppercase tracking-tighter font-bold">Model Reasoning</span>
                  </div>
                  <div className="opacity-80 italic">
                    {msg.thinking}
                  </div>
                </div>
              )}

              <div className="whitespace-pre-wrap text-[14px] leading-relaxed mb-1">
                {msg.text}
              </div>

              {/* Tool Execution Logs */}
              {msg.functionCalls && msg.functionCalls.length > 0 && (
                <div className="mt-4 pt-3 border-t border-slate-700/50 space-y-2">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Execution Trace</p>
                  {msg.functionCalls.map((fc, i) => (
                    <div key={i} className="flex items-center gap-2 text-[11px] font-mono text-cyan-400 bg-cyan-950/20 p-2 rounded border border-cyan-500/20">
                      <div className="w-1 h-1 rounded-full bg-cyan-500 animate-pulse" />
                      <span>INVOKE: <span className="font-bold">{fc.name}</span></span>
                    </div>
                  ))}
                </div>
              )}

              {/* Grounding Links */}
              {msg.groundingLinks && msg.groundingLinks.length > 0 && (
                <div className="mt-4 pt-3 border-t border-slate-700 space-y-2">
                  <div className="flex items-center gap-2 mb-1">
                    <Icons.Search />
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Verified Sources</p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {msg.groundingLinks.map((link, i) => (
                      <a 
                        key={i}
                        href={link.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="group flex items-center gap-2 px-3 py-1.5 bg-slate-900/80 border border-slate-700 hover:border-indigo-500/50 rounded-lg text-[11px] text-indigo-400 hover:text-indigo-300 transition-all"
                      >
                        <Icons.External />
                        <span className="truncate max-w-[180px] font-medium">{link.title}</span>
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start animate-in fade-in duration-300">
            <div className="bg-slate-800/50 border border-slate-700/50 rounded-2xl rounded-tl-none p-4 flex gap-1.5 items-center">
              <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
              <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
              <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce"></span>
              <span className="text-[10px] ml-2 font-bold text-slate-500 uppercase tracking-widest">Processing</span>
            </div>
          </div>
        )}
      </div>

      {/* Input Area */}
      <form onSubmit={handleSubmit} className="p-4 bg-slate-900/90 border-t border-slate-800 backdrop-blur-xl z-20">
        <div className="max-w-4xl mx-auto relative group">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder={isLoading ? "Synthesizing response..." : `Message Nexus (${mode})...`}
            disabled={isLoading}
            className="w-full bg-slate-950 border border-slate-800 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 rounded-2xl px-5 py-4 pr-14 text-sm transition-all outline-none disabled:opacity-50 shadow-inner"
          />
          <button
            type="submit"
            disabled={!input.trim() || isLoading}
            className="absolute right-2 top-1/2 -translate-y-1/2 p-2.5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 text-white rounded-xl transition-all shadow-lg shadow-indigo-600/20 active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
          </button>
        </div>
        <p className="text-center text-[9px] text-slate-600 mt-2 uppercase tracking-widest font-bold">
          Powered by Gemini 3 Advanced Pipeline
        </p>
      </form>
    </div>
  );
};

import { GoogleGenAI, GenerateContentResponse, Type, FunctionDeclaration } from "@google/genai";
import { AppMode, MessageRole } from "../types";
import { jokeTool, weatherTool, learningTool, codeGeneratorTool, toolHandlers } from "./tools";

export class GeminiService {
  private getClient() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async sendMessage(
    message: string, 
    history: any[] = [], 
    mode: AppMode = AppMode.GENERAL
  ) {
    const ai = this.getClient();

    // Choose model based on task complexity
    const model = (mode === AppMode.LEARNING || mode === AppMode.DEVELOPER) 
      ? 'gemini-3-pro-preview' 
      : 'gemini-3-flash-preview';

    // Search and Function calling can be used together in some modes
    const tools: any[] = [];
    if (mode === AppMode.NEWS || mode === AppMode.LEARNING) {
      tools.push({ googleSearch: {} });
    }

    // Always provide tools except in pure news search if we want specific tool behavior
    // but typically we can combine them. Note: Search is best on its own for news.
    if (mode !== AppMode.NEWS) {
      tools.push({
        functionDeclarations: [jokeTool, weatherTool, learningTool, codeGeneratorTool]
      });
    }

    const systemInstruction = `You are AI Nexus, a world-class AI companion.
    Current Operative Mode: ${mode}

    GUIDELINES:
    1. NEWS Mode: Provide concise, factual global news briefings using Google Search.
    2. LEARNING Mode: Act as an expert AI/ML tutor. Break down complex topics.
    3. DEVELOPER Mode: Demonstrate "Function Calling" capabilities. Show thought processes.
    4. HUMOR: Always ready to crack a joke using the get_random_joke tool when asked.
    5. TRANSPARENCY: Mention when you are using tools or searching the web.

    Note: Your API Key is handled securely. Never mention it.`;

    const config = {
      systemInstruction,
      tools,
      thinkingConfig: { 
        thinkingBudget: (mode === AppMode.DEVELOPER || mode === AppMode.LEARNING) ? 2048 : 0 
      }
    };

    try {
      const response = await ai.models.generateContent({
        model: model,
        contents: [...history, { role: 'user', parts: [{ text: message }] }],
        config: config,
      });

      const candidate = response.candidates?.[0];
      const functionCalls = response.functionCalls;

      // Extract grounding links correctly from groundingMetadata
      const groundingLinks = candidate?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) || [];

      // Handle Function Calls
      if (functionCalls && functionCalls.length > 0) {
        const toolResponses = await Promise.all(
          functionCalls.map(async (fc) => {
            const handler = toolHandlers[fc.name];
            try {
              const result = handler ? await handler(fc.args) : { error: `Tool ${fc.name} not found` };
              return {
                id: fc.id,
                name: fc.name,
                response: result
              };
            } catch (err) {
              return { id: fc.id, name: fc.name, response: { error: "Execution failed" } };
            }
          })
        );

        /**
         * CRITICAL FIX: To avoid "Function call is missing a thought signature", 
         * we MUST include the exact content parts (including 'thought' and 'functionCall')
         * from the model's turn in the next request's history.
         */
        const modelTurnParts = candidate?.content?.parts || [];

        const finalResponse = await ai.models.generateContent({
          model: model,
          contents: [
            ...history,
            { role: 'user', parts: [{ text: message }] },
            { role: 'model', parts: modelTurnParts }, 
            { role: 'tool', parts: toolResponses.map(tr => ({ functionResponse: tr })) }
          ],
          config: config
        });

        // Extract thinking from the original turn if available
        const thinkingPart = modelTurnParts.find((p: any) => 'thought' in p);

        return {
          text: finalResponse.text,
          functionCalls,
          toolResponses,
          groundingLinks: finalResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) || groundingLinks,
          thinking: (thinkingPart as any)?.thought
        };
      }

      // Extract thinking from the first response
      const thinkingPart = candidate?.content?.parts?.find((p: any) => 'thought' in p);

      return {
        text: response.text || "I processed that, but have no text response.",
        groundingLinks,
        thinking: (thinkingPart as any)?.thought
      };

    } catch (error: any) {
      console.error("Gemini API Error Details:", error);
      throw error;
    }
  }
}

