      links: [
        { title: `Introduction to ${topic} (${level})`, url: `https://developers.google.com/machine-learning/glossary#${topic.replace(/\s/g, '_')}` },
        { title: `${topic} Resource Center`, url: `https://ai.google.dev/tutorials` }
      ]
    };
