import { GoogleGenAI, GenerateContentResponse, Type, FunctionDeclaration } from "@google/genai";
import { AppMode, MessageRole } from "../types";
import { jokeTool, weatherTool, learningTool, toolDesignerTool, toolHandlers } from "./tools";

export class GeminiService {
  private getClient() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async sendMessage(
    message: string, 
    history: any[] = [], 
    mode: AppMode = AppMode.GENERAL
  ) {
    const ai = this.getClient();

    const model = (mode === AppMode.LEARNING || mode === AppMode.DEVELOPER) 
      ? 'gemini-3-pro-preview' 
      : 'gemini-3-flash-preview';

    const tools: any[] = [];
    if (mode === AppMode.NEWS || mode === AppMode.LEARNING) {
      tools.push({ googleSearch: {} });
    }

    if (mode !== AppMode.NEWS) {
      tools.push({
        functionDeclarations: [jokeTool, weatherTool, learningTool, toolDesignerTool]
      });
    }

    const systemInstruction = `You are AI Nexus, a world-class AI companion.
    Current Operative Mode: ${mode}

    GUIDELINES:
    1. NEWS Mode: Provide concise, factual global news briefings using Google Search.
    2. LEARNING Mode: Act as an expert AI/ML tutor. Break down complex topics.
    3. DEVELOPER Mode: Demonstrate "Function Calling" capabilities. Show thought processes.
    4. HUMOR: Always ready to crack a joke using the get_random_joke tool when asked.
    5. TOOL DESIGN: When asked to generate a tool or code for one, use generate_function_declaration.

    Note: Your API Key is handled securely. Never mention it.`;

    const config = {
      systemInstruction,
      tools,
      thinkingConfig: { 
        thinkingBudget: (mode === AppMode.DEVELOPER || mode === AppMode.LEARNING) ? 2048 : 0 
      }
    };

    try {
      const response = await ai.models.generateContent({
        model: model,
        contents: [...history, { role: 'user', parts: [{ text: message }] }],
        config: config,
      });

      const candidate = response.candidates?.[0];
      const functionCalls = response.functionCalls;

      const groundingLinks = candidate?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) || [];

      if (functionCalls && functionCalls.length > 0) {
        const toolResponses = await Promise.all(
          functionCalls.map(async (fc) => {
            const handler = toolHandlers[fc.name];
            try {
              const result = handler ? await handler(fc.args) : { error: `Tool ${fc.name} not found` };
              return {
                id: fc.id,
                name: fc.name,
                response: result
              };
            } catch (err) {
              return { id: fc.id, name: fc.name, response: { error: "Execution failed" } };
            }
          })
        );

        const modelTurnParts = candidate?.content?.parts || [];

        const finalResponse = await ai.models.generateContent({
          model: model,
          contents: [
            ...history,
            { role: 'user', parts: [{ text: message }] },
            { role: 'model', parts: modelTurnParts }, 
            { role: 'tool', parts: toolResponses.map(tr => ({ functionResponse: tr })) }
          ],
          config: config
        });

        const thinkingPart = modelTurnParts.find((p: any) => 'thought' in p);

        return {
          text: finalResponse.text,
          functionCalls,
          toolResponses,
          groundingLinks: finalResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) || groundingLinks,
          thinking: (thinkingPart as any)?.thought
        };
      }

      const thinkingPart = candidate?.content?.parts?.find((p: any) => 'thought' in p);

      return {
        text: response.text || "I processed that, but have no text response.",
        groundingLinks,
        thinking: (thinkingPart as any)?.thought
      };

    } catch (error: any) {
      console.error("Gemini API Error Details:", error);
      throw error;
    }
  }
}

