// Implementation of Tool Handlers
export const toolHandlers: Record<string, (args: any) => Promise<any>> = {
  get_random_joke: async ({ category = 'general' }) => {
    const jokes: Record<string, string[]> = {
      programming: [
        "Why do programmers prefer dark mode? Because light attracts bugs.",
        "A SQL query walks into a bar, walks up to two tables, and asks, 'Can I join you?'",
        "How many programmers does it take to change a light bulb? None, that's a hardware problem."
      ],
      dad: [
        "I'm afraid for the calendar. Its days are numbered.",
        "My wife said I should do lunges to stay in shape. That would be a big step forward.",
        "Why did the ocean break up with the pond? He thought she was too shallow."
      ],
      general: [
        "I told my doctor that I broke my arm in two places. He told me to stop going to those places.",
        "Parallel lines have so much in common. It’s a shame they’ll never meet."
      ]
    };
    const list = jokes[category] || jokes.general;
    return { joke: list[Math.floor(Math.random() * list.length)] };
  },
  get_weather: async ({ location, unit = 'celsius' }) => {
    const temp = Math.floor(Math.random() * 30);
    return { location, temperature: temp, unit, condition: 'Sunny' };
  },
  get_learning_resource: async ({ topic, level = 'beginner' }) => {
    // Return mock curated resources for simulation
    return {
      topic,
      level,
      links: [
        { title: `Official Google Guide: ${topic} (${level})`, url: `https://developers.google.com/machine-learning/glossary#${topic.replace(/\s/g, '_')}` },
        { title: `Advanced Research: ${topic}`, url: `https://ai.google.dev/tutorials` }
      ]
    };
  },
  generate_function_declaration: async ({ purpose, suggested_name }) => {
    const nameToUse = suggested_name || 'custom_tool';
    const safeName = nameToUse.replace(/[^a-zA-Z0-9_]/g, '');
    return {
      snippet: `import { FunctionDeclaration, Type } from '@google/genai';

/**
 * Purpose: ${purpose}
 */
export const ${safeName}: FunctionDeclaration = {
  name: '${safeName}',
  description: '${purpose}',
  parameters: {
    type: Type.OBJECT,
    properties: {
      // Define properties based on purpose
      param1: {
        type: Type.STRING,
        description: 'Description for param1'
      }
    },
    required: ['param1']
  }
};`
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, MessageRole, AppMode } from '../types';
import { Icons } from '../constants';

interface ChatInterfaceProps {
  messages: ChatMessage[];
  onSend: (text: string) => void;
  isLoading: boolean;
  mode: AppMode;
  onRefresh?: () => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onSend, isLoading, mode, onRefresh }) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isLoading) {
      onSend(input);
      setInput('');
    }
  };

  const getModeColor = (m: AppMode) => {
    switch (m) {
      case AppMode.NEWS: return 'text-amber-400 bg-amber-400/10 border-amber-400/20';
      case AppMode.LEARNING: return 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
      case AppMode.DEVELOPER: return 'text-purple-400 bg-purple-400/10 border-purple-400/20';
      default: return 'text-indigo-400 bg-indigo-400/10 border-indigo-400/20';
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-x border-slate-800 shadow-2xl overflow-hidden relative">
      {/* Header */}
      <div className="p-4 border-b border-slate-800 bg-slate-900/80 backdrop-blur-xl flex justify-between items-center sticky top-0 z-20">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl shadow-lg shadow-indigo-500/20">
            <Icons.Robot />
          </div>
          <div>
            <h1 className="font-bold text-lg tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">AI Nexus</h1>
            <div className="flex items-center gap-2">
              <span className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-indigo-500 animate-ping' : 'bg-green-500'}`} />
              <div className="flex items-center gap-2">
                <span className={`text-[10px] font-bold uppercase tracking-widest border px-2 py-0.5 rounded ${getModeColor(mode)}`}>
                  {mode}
                </span>
                {mode === AppMode.NEWS && (
                  <button 
                    onClick={onRefresh}
                    disabled={isLoading}
                    className="flex items-center gap-1.5 px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest text-amber-400 bg-amber-400/5 hover:bg-amber-400/20 border border-amber-400/20 rounded-md transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none"
                    title="Refresh World News"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/></svg>
                    Sync News
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-slate-950"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-6 text-center px-8">
            <div className="p-6 bg-slate-900/50 rounded-full border border-slate-800 animate-pulse">
               <Icons.Robot />
            </div>
            <div className="max-w-md">
              <p className="text-xl font-bold text-slate-200 mb-2">Initialize Connection</p>
              <p className="text-sm leading-relaxed text-slate-400">
                Current Mode: <span className="font-mono text-indigo-400">{mode.toUpperCase()}</span>.
                I'm ready to assist with global briefings, ML tutorials, or system tool testing.
              </p>
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
          >
            <div className={`max-w-[88%] rounded-2xl p-4 shadow-xl border ${
              msg.role === MessageRole.USER 
                ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                : 'bg-slate-800/90 backdrop-blur-sm text-slate-100 border-slate-700/50 rounded-tl-none'
            }`}>
              {/* Thinking Segment */}
              {msg.thinking && (
                <div className="mb-4 p-3 bg-black/40 rounded-xl border border-slate-700/50 text-[11px] text-slate-300 font-mono overflow-hidden">
                  <div className="flex items-center gap-2 mb-2 text-indigo-400 border-b border-slate-800 pb-1">
                    <Icons.Terminal />
                    <span className="uppercase tracking-tighter font-bold">Model Reasoning</span>
                  </div>
                  <div className="opacity-80 italic">
                    {msg.thinking}
                  </div>
                </div>
              )}

              <div className="whitespace-pre-wrap text-[14px] leading-relaxed mb-1">
                {msg.text}
              </div>

              {/* Tool Execution Logs */}
              {msg.functionCalls && msg.functionCalls.length > 0 && (
                <div className="mt-4 pt-3 border-t border-slate-700/50 space-y-2">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Execution Trace</p>
