                          #{tag}
                        </span>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>

        <div className="p-6 border-t border-slate-800 bg-slate-900">
          <div className="p-3 bg-indigo-500/5 rounded-xl border border-indigo-500/20">
            <p className="text-[10px] font-bold text-indigo-400 uppercase mb-1">Status</p>
            <p className="text-xs text-slate-400">Gemini 3 Pro Pipeline Active</p>
          </div>
        </div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col min-w-0">
        <ChatInterface 
          messages={messages} 
          onSend={handleSend} 
          isLoading={isLoading} 
          mode={mode} 
          onRefresh={mode === AppMode.NEWS ? handleRefreshNews : undefined}
        />
      </main>

      {/* Tool Inspector Panel */}
      {mode === AppMode.DEVELOPER && (
        <aside className="w-80 border-l border-slate-800 bg-slate-950 p-6 overflow-y-auto hidden xl:block animate-in slide-in-from-right duration-500">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-6">Tool Inspector</h2>

          <div className="space-y-8">
            <section>
              <h3 className="text-sm font-semibold mb-3 flex items-center gap-2 text-indigo-400">
                <Icons.Code /> Live Sandbox
              </h3>
              <p className="text-xs text-slate-400 mb-4 leading-relaxed">
                The model can currently "see" {customTools.length + 4} tools. Any tool you define in the Workshop is instantly available for conversation.
              </p>
              <div className="space-y-2">
                <div className="text-[10px] font-bold text-slate-500 uppercase mb-1">Built-in:</div>
                {['get_random_joke', 'get_weather', 'get_learning_resource', 'generate_function_declaration'].map(t => (
                  <div key={t} className="flex items-center gap-2 px-2 py-1 bg-slate-900/50 rounded font-mono text-[9px] text-slate-400 border border-slate-800/50">
                    <div className="w-1 h-1 bg-green-500/50 rounded-full" />
