            <section className="p-4 bg-indigo-600/10 rounded-xl border border-indigo-500/20">
              <p className="text-xs font-medium text-indigo-300 mb-2">Simulated Responses:</p>
              <p className="text-xs text-slate-400 leading-relaxed">
