// Implementation of Tool Handlers
export const toolHandlers: Record<string, (args: any) => Promise<any>> = {
  get_random_joke: async ({ category = 'general' }) => {
    const jokes: Record<string, string[]> = {
      programming: [
        "Why do programmers prefer dark mode? Because light attracts bugs.",
        "A SQL query walks into a bar, walks up to two tables, and asks, 'Can I join you?'",
        "How many programmers does it take to change a light bulb? None, that's a hardware problem."
      ],
      dad: [
        "I'm afraid for the calendar. Its days are numbered.",
        "My wife said I should do lunges to stay in shape. That would be a big step forward.",
        "Why did the ocean break up with the pond? He thought she was too shallow."
      ],
      general: [
        "I told my doctor that I broke my arm in two places. He told me to stop going to those places.",
        "Parallel lines have so much in common. It’s a shame they’ll never meet."
      ]
    };
    const list = jokes[category] || jokes.general;
    return { joke: list[Math.floor(Math.random() * list.length)] };
  },
  get_weather: async ({ location, unit = 'celsius' }) => {
    const temp = Math.floor(Math.random() * 30);
    return { location, temperature: temp, unit, condition: 'Sunny' };
  },
  get_learning_resource: async ({ topic, level = 'beginner' }) => {
    // Return mock curated resources for simulation
    return {
      topic,
      level,
      links: [
        { title: `Official Google Guide: ${topic} (${level})`, url: `https://developers.google.com/machine-learning/glossary#${topic.replace(/\s/g, '_')}` },
        { title: `Advanced Research: ${topic}`, url: `https://ai.google.dev/tutorials` }
      ]
    };
  },
  analyze_code_structure: async ({ code, language = 'auto' }) => {
    const lines = code.split('\n').length;
    const hasLoops = /for|while/.test(code);
    const hasConditionals = /if|else|switch/.test(code);
    const hasFunctions = /function|def|=>/.test(code);
    const complexityScore = (lines * 0.1) + (hasLoops ? 2 : 0) + (hasConditionals ? 1 : 0);

    return {
      analysis_report: {
        detected_language: language,
        line_count: lines,
        complexity_rating: complexityScore > 5 ? 'High' : complexityScore > 2 ? 'Medium' : 'Low',
        features: {
          iteration: hasLoops,
          logic_gates: hasConditionals,
          modularization: hasFunctions
        },
        engine_status: "Structural scanning complete. Contextual metadata extracted."
      }
    };
  },
  generate_function_declaration: async ({ purpose, suggested_name }) => {
    const nameToUse = suggested_name || 'custom_tool';
    const safeName = nameToUse.replace(/[^a-zA-Z0-9_]/g, '');
    return {
      snippet: `import { FunctionDeclaration, Type } from '@google/genai';

/**
 * Purpose: ${purpose}
 */
export const ${safeName}: FunctionDeclaration = {
  name: '${safeName}',
  description: '${purpose}',
  parameters: {
    type: Type.OBJECT,
    properties: {
      // Define properties based on purpose
      param1: {
        type: Type.STRING,
        description: 'Description for param1'
      }
    },
    required: ['param1']
  }
};`
    };
  }
};

import { GoogleGenAI, GenerateContentResponse, Type, FunctionDeclaration } from "@google/genai";
import { AppMode, MessageRole, CustomTool } from "../types";
import { jokeTool, weatherTool, learningTool, toolDesignerTool, codeExplainerTool, toolHandlers } from "./tools";

export class GeminiService {
  private getClient() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async sendMessage(
    message: string, 
    history: any[] = [], 
    mode: AppMode = AppMode.GENERAL,
    customTools: CustomTool[] = []
  ) {
    const ai = this.getClient();

    const model = (mode === AppMode.LEARNING || mode === AppMode.DEVELOPER) 
      ? 'gemini-3-pro-preview' 
      : 'gemini-3-flash-preview';

    const tools: any[] = [];

    // Add Search if applicable
    if (mode === AppMode.NEWS || mode === AppMode.LEARNING) {
      tools.push({ googleSearch: {} });
    }

    // Core Tools
    const functionDeclarations: FunctionDeclaration[] = [];
    if (mode !== AppMode.NEWS) {
      functionDeclarations.push(jokeTool, weatherTool, learningTool, toolDesignerTool, codeExplainerTool);

      // Inject User Custom Tools
      customTools.forEach(ct => {
        functionDeclarations.push({
          name: ct.name,
          description: ct.description,
          parameters: ct.parameters
        });
      });

      if (functionDeclarations.length > 0) {
        tools.push({ functionDeclarations });
      }
    }

    const currentDate = new Date().toLocaleString();
    const systemInstruction = `You are AI Nexus, a world-class AI companion.
    Current Operative Mode: ${mode}
    Current Time/Date: ${currentDate}

    GUIDELINES:
    1. NEWS Mode: Provide concise, factual global news briefings using Google Search. Focus on events from the last 24-48 hours.
    2. LEARNING Mode: Act as an expert AI/ML tutor.
    3. DEVELOPER Mode: You have access to built-in tools AND user-defined custom tools. 
    4. CODE ANALYSIS: Use 'analyze_code_structure' when asked to explain or review code. Use the report it generates to provide a natural language explanation of the functionality.
    5. CUSTOM TOOLS: If you see tools like ${customTools.map(t => t.name).join(', ')}, these were created by the user. Use them if they fit the request.

    Note: Your API Key is handled securely. Never mention it.`;

    const config = {
      systemInstruction,
      tools,
      thinkingConfig: { 
        thinkingBudget: (mode === AppMode.DEVELOPER || mode === AppMode.LEARNING) ? 2048 : 0 
      }
    };

    try {
      const response = await ai.models.generateContent({
        model: model,
        contents: [...history, { role: 'user', parts: [{ text: message }] }],
        config: config,
      });

      const candidate = response.candidates?.[0];
      const functionCalls = response.functionCalls;

      const groundingLinks = candidate?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) || [];

      if (functionCalls && functionCalls.length > 0) {
        const toolResponses = await Promise.all(
          functionCalls.map(async (fc) => {
            const handler = toolHandlers[fc.name];
            if (handler) {
              try {
                const result = await handler(fc.args);
                return { id: fc.id, name: fc.name, response: result };
              } catch (err) {
                return { id: fc.id, name: fc.name, response: { error: "Execution failed" } };
              }
            } else {
              // Simulated response for custom tools or unknown tools
              return { 
                id: fc.id, 
                name: fc.name, 
                response: { 
                  status: "success", 
                  message: `Simulated execution of ${fc.name} successful.`,
                  received_args: fc.args
                } 
              };
            }
          })
        );

        const modelTurnParts = candidate?.content?.parts || [];

        const finalResponse = await ai.models.generateContent({
          model: model,
          contents: [
            ...history,
            { role: 'user', parts: [{ text: message }] },
            { role: 'model', parts: modelTurnParts }, 
            { role: 'tool', parts: toolResponses.map(tr => ({ functionResponse: tr })) }
          ],
          config: config
        });

        const thinkingPart = modelTurnParts.find((p: any) => 'thought' in p);

        return {
          text: finalResponse.text,
          functionCalls,
          toolResponses,
          groundingLinks: finalResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) || groundingLinks,
          thinking: (thinkingPart as any)?.thought
        };
      }

      const thinkingPart = candidate?.content?.parts?.find((p: any) => 'thought' in p);

      return {
        text: response.text || "I processed that, but have no text response.",
        groundingLinks,
        thinking: (thinkingPart as any)?.thought
      };

    } catch (error: any) {
      console.error("Gemini API Error Details:", error);
      throw error;
    }
  }
}

