import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { ChatInterface } from './components/ChatInterface';
import { SidebarNavigation } from './components/SidebarNavigation';
import { ChatMessage, MessageRole, AppMode, CustomTool } from './types';
import { GeminiService } from './services/geminiService';
import { Icons } from './constants';

const App: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [mode, setMode] = useState<AppMode>(AppMode.GENERAL);
  const [customTools, setCustomTools] = useState<CustomTool[]>(() => {
    const saved = localStorage.getItem('nexus_custom_tools');
    return saved ? JSON.parse(saved) : [];
  });

  const gemini = useMemo(() => new GeminiService(), []);

  useEffect(() => {
    localStorage.setItem('nexus_custom_tools', JSON.stringify(customTools));
  }, [customTools]);

  const handleSend = useCallback(async (text: string) => {
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);

    try {
      const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
      }));

      const response = await gemini.sendMessage(text, history, mode, customTools);

      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: response.text || "I'm sorry, I couldn't process that.",
        timestamp: Date.now(),
        functionCalls: response.functionCalls,
        toolResponses: response.toolResponses,
        groundingLinks: response.groundingLinks,
        thinking: response.thinking
      };

      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, {
        id: 'error',
        role: MessageRole.MODEL,
        text: "Error: I encountered a problem connecting to the brain center.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
    }
  }, [messages, mode, gemini, customTools]);

  const handleRefreshNews = useCallback(() => {
    handleSend("Perform a deep real-time scan of global news sources. Provide a fresh briefing on the most important global news stories across technology, world politics, and science from the last 24 hours.");
  }, [handleSend]);

  const changeMode = (newMode: AppMode) => {
    setMode(newMode);
    const systemMsg: ChatMessage = {
      id: `sys-${Date.now()}`,
      role: MessageRole.MODEL,
      text: `Switching to ${newMode.toUpperCase()} mode. How can I help you in this context?`,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, systemMsg]);
  };

  const addCustomTool = (tool: CustomTool) => {
    setCustomTools(prev => [...prev, tool]);
  };

  const removeCustomTool = (id: string) => {
    setCustomTools(prev => prev.filter(t => t.id !== id));
  };

  return (
    <div className="flex h-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <SidebarNavigation 
        currentMode={mode}
        onModeChange={changeMode}
        onSend={handleSend}
        customTools={customTools}
        onAddTool={addCustomTool}
        onRemoveTool={removeCustomTool}
      />

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col min-w-0">
        <ChatInterface 
          messages={messages} 
          onSend={handleSend} 
          isLoading={isLoading} 
          mode={mode} 
          onRefresh={mode === AppMode.NEWS ? handleRefreshNews : undefined}
        />
      </main>

      {/* Tool Inspector Panel (Visible in Developer Mode) */}
      {mode === AppMode.DEVELOPER && (
        <aside className="w-80 border-l border-slate-800 bg-slate-950 p-6 overflow-y-auto hidden xl:block animate-in slide-in-from-right duration-500">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-6">Execution Log</h2>

          <div className="space-y-8">
            <section>
              <h3 className="text-sm font-semibold mb-3 flex items-center gap-2 text-indigo-400">
                <Icons.Code /> Live Environment
              </h3>
              <p className="text-xs text-slate-400 mb-4 leading-relaxed">
                The model can currently "see" {customTools.length + 5} tools.
              </p>
              <div className="space-y-2">
                <div className="text-[10px] font-bold text-slate-500 uppercase mb-1 tracking-wider">System Functions:</div>
                {['get_random_joke', 'get_weather', 'get_learning_resource', 'analyze_code_structure', 'generate_function_declaration'].map(t => (
                  <div key={t} className="flex items-center gap-2 px-2 py-1 bg-slate-900/50 rounded font-mono text-[9px] text-slate-400 border border-slate-800/50">
                    <div className="w-1 h-1 bg-green-500/50 rounded-full" />
                    {t}
                  </div>
                ))}
                {customTools.length > 0 && (
                  <>
                    <div className="text-[10px] font-bold text-indigo-500 uppercase mt-4 mb-1 tracking-wider">User Defined:</div>
                    {customTools.map(t => (
                      <div key={t.id} className="flex items-center gap-2 px-2 py-1 bg-indigo-500/5 rounded font-mono text-[9px] text-indigo-300 border border-indigo-500/20">
                        <div className="w-1 h-1 bg-indigo-400 rounded-full animate-pulse" />
                        {t.name}
                      </div>
                    ))}
                  </>
                )}
              </div>
            </section>

            <section className="p-4 bg-slate-900/50 rounded-xl border border-slate-800">
              <p className="text-[10px] font-bold text-slate-500 uppercase mb-2">Debugger Info</p>
              <div className="space-y-2 text-[10px] font-mono">
                <div className="flex justify-between">
                  <span className="text-slate-600">Model:</span>
                  <span className="text-cyan-400">gemini-3-pro</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-600">Region:</span>
                  <span className="text-cyan-400">Global-01</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-600">Latency:</span>
                  <span className="text-green-500">~1.2s</span>
                </div>
              </div>
            </section>
          </div>
        </aside>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, MessageRole, AppMode } from '../types';
import { Icons } from '../constants';

interface ChatInterfaceProps {
  messages: ChatMessage[];
  onSend: (text: string) => void;
  isLoading: boolean;
  mode: AppMode;
  onRefresh?: () => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onSend, isLoading, mode, onRefresh }) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isLoading) {
      onSend(input);
      setInput('');
    }
  };

  const getModeColor = (m: AppMode) => {
    switch (m) {
      case AppMode.NEWS: return 'text-amber-400 bg-amber-400/10 border-amber-400/20';
      case AppMode.LEARNING: return 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
      case AppMode.DEVELOPER: return 'text-purple-400 bg-purple-400/10 border-purple-400/20';
      default: return 'text-indigo-400 bg-indigo-400/10 border-indigo-400/20';
    }
  };

  const renderComplexityIndicator = (rating: string) => {
    let color = 'bg-slate-700';
    let width = 'w-0';
    let textColor = 'text-slate-400';

    if (rating === 'Low') {
      color = 'bg-green-500';
      width = 'w-1/3';
      textColor = 'text-green-400';
    } else if (rating === 'Medium') {
      color = 'bg-yellow-500';
      width = 'w-2/3';
      textColor = 'text-yellow-400';
    } else if (rating === 'High') {
      color = 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]';
      width = 'w-full';
      textColor = 'text-red-400';
    }

    return (
      <div className="mt-2 p-2 bg-slate-900/50 rounded-lg border border-slate-700/50">
        <div className="flex justify-between items-center mb-1.5">
          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">Complexity Analysis</span>
          <span className={`text-[10px] font-mono font-bold ${textColor}`}>{rating}</span>
        </div>
        <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
          <div className={`h-full ${color} ${width} transition-all duration-700 ease-out`} />
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-x border-slate-800 shadow-2xl overflow-hidden relative">
      {/* Header */}
      <div className="p-4 border-b border-slate-800 bg-slate-900/80 backdrop-blur-xl flex justify-between items-center sticky top-0 z-20">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl shadow-lg shadow-indigo-500/20">
            <Icons.Robot />
          </div>
          <div>
            <h1 className="font-bold text-lg tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">AI Nexus</h1>
            <div className="flex items-center gap-2">
              <span className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-indigo-500 animate-ping' : 'bg-green-500'}`} />
              <div className="flex items-center gap-2">
                <span className={`text-[10px] font-bold uppercase tracking-widest border px-2 py-0.5 rounded ${getModeColor(mode)}`}>
                  {mode}
                </span>
                {mode === AppMode.NEWS && (
                  <button 
                    onClick={onRefresh}
                    disabled={isLoading}
                    className="flex items-center gap-1.5 px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest text-amber-400 bg-amber-400/5 hover:bg-amber-400/20 border border-amber-400/20 rounded-md transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none"
                    title="Refresh World News"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/></svg>
                    Sync News
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-slate-950"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-6 text-center px-8">
            <div className="p-6 bg-slate-900/50 rounded-full border border-slate-800 animate-pulse">
               <Icons.Robot />
            </div>
            <div className="max-w-md">
              <p className="text-xl font-bold text-slate-200 mb-2">Initialize Connection</p>
              <p className="text-sm leading-relaxed text-slate-400">
                Current Mode: <span className="font-mono text-indigo-400">{mode.toUpperCase()}</span>.
                I'm ready to assist with global briefings, ML tutorials, or system tool testing.
              </p>
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
          >
            <div className={`max-w-[88%] rounded-2xl p-4 shadow-xl border ${
              msg.role === MessageRole.USER 
                ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                : 'bg-slate-800/90 backdrop-blur-sm text-slate-100 border-slate-700/50 rounded-tl-none'
            }`}>
              {/* Thinking Segment */}
              {msg.thinking && (
                <div className="mb-4 p-3 bg-black/40 rounded-xl border border-slate-700/50 text-[11px] text-slate-300 font-mono overflow-hidden">
                  <div className="flex items-center gap-2 mb-2 text-indigo-400 border-b border-slate-800 pb-1">
                    <Icons.Terminal />
                    <span className="uppercase tracking-tighter font-bold">Model Reasoning</span>
                  </div>
                  <div className="opacity-80 italic">
                    {msg.thinking}
                  </div>
                </div>
              )}

              <div className="whitespace-pre-wrap text-[14px] leading-relaxed mb-1">
                {msg.text}
              </div>

              {/* Tool Execution Logs & Rich Previews */}
              {(msg.functionCalls && msg.functionCalls.length > 0) && (
                <div className="mt-4 pt-3 border-t border-slate-700/50 space-y-2">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Execution Trace</p>
                  {msg.functionCalls.map((fc, i) => {
                    const response = msg.toolResponses?.find(tr => tr.name === fc.name || tr.id === fc.id)?.response;
                    const report = response?.analysis_report;

                    return (
                      <div key={i} className="space-y-2">
                        <div className="flex items-center gap-2 text-[11px] font-mono text-cyan-400 bg-cyan-950/20 p-2 rounded border border-cyan-500/20">
                          <div className="w-1 h-1 rounded-full bg-cyan-500 animate-pulse" />
                          <span>INVOKE: <span className="font-bold">{fc.name}</span></span>
                        </div>
                        {fc.name === 'analyze_code_structure' && report && (
                          <div className="animate-in fade-in zoom-in-95 duration-500">
                             {renderComplexityIndicator(report.complexity_rating)}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Grounding Links */}
              {msg.groundingLinks && msg.groundingLinks.length > 0 && (
                <div className="mt-4 pt-3 border-t border-slate-700 space-y-2">
                  <div className="flex items-center gap-2 mb-1">
