                      <a 
                        key={i}
                        href={link.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="group flex items-center gap-2 px-3 py-1.5 bg-slate-900/80 border border-slate-700 hover:border-indigo-500/50 rounded-lg text-[11px] text-indigo-400 hover:text-indigo-300 transition-all"
                      >
                        <Icons.External />
