import React, { useState, useEffect } from 'react';
import { CustomTool } from '../types';
import { Icons } from '../constants';

interface CustomToolManagerProps {
  tools: CustomTool[];
  onAdd: (tool: CustomTool) => void;
  onRemove: (id: string) => void;
  onDesignRequest: (description: string) => void;
}

export const CustomToolManager: React.FC<CustomToolManagerProps> = ({ 
  tools, 
  onAdd, 
  onRemove,
  onDesignRequest 
}) => {
  const [isAdding, setIsAdding] = useState(false);
  const [designInput, setDesignInput] = useState('');
  const [validationStatus, setValidationStatus] = useState<{ message: string; isError: boolean } | null>(null);

  const DEFAULT_PARAMS = '{\n  "type": "OBJECT",\n  "properties": {\n    "query": {\n      "type": "STRING",\n      "description": "The search term or topic to explore"\n    }\n  },\n  "required": ["query"]\n}';

  const [form, setForm] = useState({
    name: '',
    description: '',
    parameters: DEFAULT_PARAMS
  });

  const validateSchema = (schema: any, path: string = 'root'): string | null => {
    if (!schema || typeof schema !== 'object') return `${path}: Must be an object`;

    // Check type
    const validTypes = ['STRING', 'NUMBER', 'INTEGER', 'BOOLEAN', 'ARRAY', 'OBJECT', 'NULL'];
    if (!schema.type) return `${path}: Missing 'type' field`;
    if (!validTypes.includes(schema.type)) return `${path}: Invalid type '${schema.type}'`;

    // Check description (required for properties, recommended for root)
    if (path !== 'root' && (!schema.description || schema.description.trim().length < 5)) {
      return `${path}: Property needs a descriptive 'description' (min 5 chars)`;
    }

    if (schema.type === 'OBJECT') {
      if (!schema.properties || typeof schema.properties !== 'object' || Object.keys(schema.properties).length === 0) {
        return `${path}: 'OBJECT' must contain at least one property in 'properties'`;
      }
      for (const [key, value] of Object.entries(schema.properties)) {
        const error = validateSchema(value, `${path}.properties.${key}`);
        if (error) return error;
      }
    }

    if (schema.type === 'ARRAY') {
      if (!schema.items) return `${path}: 'ARRAY' type must have an 'items' definition`;
      const error = validateSchema(schema.items, `${path}.items`);
      if (error) return error;
    }

    return null;
  };

  useEffect(() => {
    if (!form.parameters.trim()) {
      setValidationStatus({ message: 'Parameters cannot be empty', isError: true });
      return;
    }

    try {
      const parsed = JSON.parse(form.parameters);
      const schemaError = validateSchema(parsed);

      if (schemaError) {
        setValidationStatus({ message: schemaError, isError: true });
      } else {
        setValidationStatus({ message: 'Schema structure is valid', isError: false });
      }
    } catch (e: any) {
      setValidationStatus({ message: `JSON Parse Error: ${e.message}`, isError: true });
    }
  }, [form.parameters]);

  const handleSave = () => {
    try {
      const parsedParams = JSON.parse(form.parameters);
      const schemaError = validateSchema(parsedParams);

      if (schemaError) {
        setValidationStatus({ message: schemaError, isError: true });
        return;
      }

      onAdd({
        id: Date.now().toString(),
        name: form.name.trim() || 'unnamed_tool',
        description: form.description.trim() || 'No description provided',
        parameters: parsedParams
      });
      setIsAdding(false);
      setForm({ name: '', description: '', parameters: DEFAULT_PARAMS });
      setDesignInput('');
    } catch (e: any) {
      setValidationStatus({ message: e.message, isError: true });
    }
  };

  const injectTemplate = (type: string) => {
    try {
      const current = JSON.parse(form.parameters);
      if (!current.properties) current.properties = {};

      const newKey = `param_${Object.keys(current.properties).length + 1}`;

      let newProp: any = { 
        type, 
        description: `This parameter represents the ${newKey.replace('_', ' ')} logic.` 
      };

      if (type === 'ARRAY') {
        newProp.items = { type: 'STRING', description: 'Item in the collection' };
      } else if (type === 'OBJECT') {
        newProp.properties = { 
          sub_param: { type: 'STRING', description: 'A nested parameter' } 
        };
      }

      current.properties[newKey] = newProp;
      setForm({ ...form, parameters: JSON.stringify(current, null, 2) });
    } catch (e) {
      setValidationStatus({ message: "Fix current JSON errors before adding nodes", isError: true });
    }
  };

  const prettify = () => {
    try {
      const obj = JSON.parse(form.parameters);
      setForm({ ...form, parameters: JSON.stringify(obj, null, 2) });
    } catch (e) {}
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-sm font-semibold flex items-center gap-2 text-indigo-400">
          <Icons.Code /> Custom Workshop
        </h3>
        <button 
          onClick={() => {
            setIsAdding(!isAdding);
            if (!isAdding) setForm({ ...form, parameters: DEFAULT_PARAMS });
          }}
          className={`text-[10px] px-2 py-1 rounded-md transition-all uppercase font-bold border ${
            isAdding 
              ? 'bg-slate-800 text-slate-400 border-slate-700 hover:text-white' 
              : 'bg-indigo-600 text-white border-indigo-500 hover:bg-indigo-500 shadow-lg shadow-indigo-600/20'
          }`}
        >
          {isAdding ? 'Cancel' : 'New Tool'}
        </button>
      </div>

      {isAdding ? (
        <div className="p-4 bg-slate-900 border border-slate-800 rounded-xl space-y-4 animate-in fade-in zoom-in-95 duration-200">
          <div className="space-y-2">
            <label className="text-[10px] uppercase font-bold text-slate-500 flex justify-between">
              <span>Schema Generation</span>
              <span className="text-indigo-400/50">SMART DESIGN</span>
            </label>
            <div className="flex gap-2">
              <input 
                type="text" 
                placeholder="Describe tool (e.g. 'Search for books by author')"
                value={designInput}
                onChange={(e) => setDesignInput(e.target.value)}
                className="flex-1 bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-xs outline-none focus:border-indigo-500 transition-colors placeholder:text-slate-700"
              />
              <button 
                onClick={() => onDesignRequest(designInput)}
                disabled={!designInput.trim()}
                className="p-2 bg-indigo-500/10 border border-indigo-500/20 rounded-lg hover:bg-indigo-500/20 text-indigo-400 disabled:opacity-30 disabled:grayscale transition-all active:scale-90"
                title="Ask Nexus to design this tool"
              >
                <Icons.Robot />
              </button>
            </div>
          </div>

          <div className="space-y-3 pt-4 border-t border-slate-800">
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-slate-500">Identifier</label>
                <input 
                  placeholder="e.g. fetch_data" 
                  value={form.name}
                  onChange={e => setForm({...form, name: e.target.value.replace(/\s/g, '_')})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-lg px-2.5 py-2 text-xs font-mono text-indigo-300 outline-none focus:border-indigo-500"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-slate-500">Maturity</label>
                <div className="h-9 flex items-center px-3 bg-slate-950 border border-slate-800 rounded-lg text-[10px] text-emerald-500 font-bold uppercase tracking-widest">
                  Alpha
                </div>
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[9px] uppercase font-bold text-slate-500">Core Purpose</label>
              <textarea 
                placeholder="Detailed explanation for the AI model..." 
                value={form.description}
                onChange={e => setForm({...form, description: e.target.value})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-2.5 py-2 text-xs min-h-[60px] outline-none focus:border-indigo-500 resize-none"
              />
            </div>

            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <label className="text-[9px] uppercase font-bold text-slate-500">Parameters (OpenAPI Subset)</label>
                <button onClick={prettify} className="text-[8px] px-2 py-1 bg-slate-800 rounded text-slate-400 hover:text-white uppercase font-bold transition-colors">Format JSON</button>
              </div>

              <div className="flex flex-wrap gap-1.5 py-1">
                {['STRING', 'NUMBER', 'BOOLEAN', 'ARRAY', 'OBJECT'].map(t => (
                  <button 
                    key={t}
                    onClick={() => injectTemplate(t)}
                    className="text-[9px] px-2 py-1 bg-indigo-500/5 border border-indigo-500/10 rounded-md text-indigo-400/80 hover:bg-indigo-500/10 hover:text-indigo-300 transition-all font-mono"
                  >
                    + {t}
                  </button>
                ))}
              </div>

              <div className="relative group">
                <textarea 
                  value={form.parameters}
                  onChange={e => setForm({...form, parameters: e.target.value})}
                  className={`w-full bg-slate-950 border rounded-xl px-3 py-2.5 text-[10px] font-mono min-h-[200px] outline-none transition-all ${
                    validationStatus?.isError 
                      ? 'border-red-500/30 text-red-400 bg-red-500/[0.02]' 
                      : 'border-slate-800 text-cyan-400/90 focus:border-indigo-500/50'
                  }`}
                  spellCheck={false}
                />
                {validationStatus && (
                  <div className={`absolute bottom-2 left-2 right-2 text-[8px] font-mono px-2 py-1 rounded border backdrop-blur-md transition-all ${
                    validationStatus.isError 
                      ? 'bg-red-950/80 text-red-200 border-red-500/30' 
                      : 'bg-emerald-950/80 text-emerald-200 border-emerald-500/30 opacity-0 group-hover:opacity-100'
                  }`}>
                    {validationStatus.message}
                  </div>
                )}
              </div>
            </div>

            <button 
              onClick={handleSave}
              disabled={validationStatus?.isError}
              className="w-full py-3 bg-indigo-600 rounded-xl font-bold text-xs hover:bg-indigo-500 disabled:opacity-40 disabled:bg-slate-800 shadow-xl shadow-indigo-600/10 active:scale-[0.98] transition-all"
            >
              Deploy Custom Tool
            </button>
          </div>
        </div>
      ) : (
        <div className="space-y-3 max-h-[450px] overflow-y-auto pr-1 scrollbar-hide">
          {tools.length === 0 ? (
            <div className="p-10 border border-slate-800 border-dashed rounded-2xl text-center bg-slate-900/20">
              <div className="w-12 h-12 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-600">
                <Icons.Code />
              </div>
              <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">No custom logic active</p>
              <p className="text-[9px] text-slate-600 mt-2 leading-relaxed">Design tools to extend Nexus's capabilities with your own function definitions.</p>
            </div>
          ) : (
            tools.map(tool => (
              <div key={tool.id} className="group p-4 bg-slate-900/40 border border-slate-800/60 rounded-xl hover:border-indigo-500/40 transition-all shadow-sm relative overflow-hidden">
                <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500/20" />
                <div className="flex justify-between items-start mb-2 pl-2">
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.5)] animate-pulse" />
                    <span className="text-xs font-mono font-bold text-indigo-300">{tool.name}</span>
                  </div>
                  <button 
                    onClick={() => onRemove(tool.id)}
                    className="opacity-0 group-hover:opacity-100 p-1.5 text-slate-500 hover:text-red-400 transition-all hover:bg-red-400/10 rounded-lg"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>
                  </button>
                </div>
                <p className="text-[10px] text-slate-400 line-clamp-2 leading-relaxed px-2 mb-3">{tool.description}</p>
                <div className="px-2 flex flex-wrap gap-1.5">
                  {Object.keys(tool.parameters?.properties || {}).map(p => (
                    <span key={p} className="text-[8px] font-mono px-2 py-0.5 bg-slate-800/80 border border-slate-700/50 rounded text-slate-400 group-hover:border-indigo-500/20 transition-colors">
                      {p}
                    </span>
                  ))}
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, MessageRole, AppMode } from '../types';
import { Icons } from '../constants';

interface ChatInterfaceProps {
  messages: ChatMessage[];
  onSend: (text: string) => void;
  isLoading: boolean;
  mode: AppMode;
  onRefresh?: () => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onSend, isLoading, mode, onRefresh }) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isLoading) {
      onSend(input);
      setInput('');
    }
  };

  const getModeColor = (m: AppMode) => {
    switch (m) {
      case AppMode.NEWS: return 'text-amber-400 bg-amber-400/10 border-amber-400/20';
      case AppMode.LEARNING: return 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
      case AppMode.DEVELOPER: return 'text-purple-400 bg-purple-400/10 border-purple-400/20';
      default: return 'text-indigo-400 bg-indigo-400/10 border-indigo-400/20';
    }
  };

  const getLoadingText = (m: AppMode) => {
    switch (m) {
      case AppMode.NEWS: return 'Scanning global feeds...';
      case AppMode.LEARNING: return 'Preparing academy module...';
      case AppMode.DEVELOPER: return 'Running execution trace...';
      default: return 'Nexus is thinking...';
    }
  };

  const renderComplexityIndicator = (rating: string) => {
    let color = 'bg-slate-700';
    let width = 'w-0';
    let textColor = 'text-slate-400';

    if (rating === 'Low') {
      color = 'bg-green-500';
      width = 'w-1/3';
