      width = 'w-2/3';
      textColor = 'text-yellow-400';
    } else if (rating === 'High') {
      color = 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]';
      width = 'w-full';
      textColor = 'text-red-400';
