    </aside>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, MessageRole, AppMode } from '../types';
import { Icons } from '../constants';

interface ChatInterfaceProps {
  messages: ChatMessage[];
  onSend: (text: string) => void;
  isLoading: boolean;
  mode: AppMode;
  onRefresh?: (category?: string) => void;
  onMenuToggle?: () => void;
}

const NEWS_CATEGORIES = [
  { id: 'world', label: 'Global', icon: '🌍' },
  { id: 'technology', label: 'Tech', icon: '💻' },
  { id: 'science', label: 'Science', icon: '🧪' },
  { id: 'business', label: 'Business', icon: '📈' },
  { id: 'entertainment', label: 'Culture', icon: '🎬' },
];

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ 
  messages, 
  onSend, 
  isLoading, 
  mode, 
  onRefresh,
  onMenuToggle
}) => {
  const [input, setInput] = useState('');
  const [activeNewsTab, setActiveNewsTab] = useState('world');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isLoading) {
      onSend(input);
      setInput('');
    }
  };

  const handleNewsTabClick = (category: string) => {
    setActiveNewsTab(category);
    if (onRefresh) onRefresh(category);
  };

  const getModeColor = (m: AppMode) => {
    switch (m) {
      case AppMode.NEWS: return 'text-amber-400 bg-amber-400/10 border-amber-400/20';
      case AppMode.LEARNING: return 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
      case AppMode.DEVELOPER: return 'text-purple-400 bg-purple-400/10 border-purple-400/20';
      default: return 'text-indigo-400 bg-indigo-400/10 border-indigo-400/20';
    }
  };

  const getLoadingText = (m: AppMode) => {
    switch (m) {
      case AppMode.NEWS: return 'Scanning global feeds...';
      case AppMode.LEARNING: return 'Preparing academy module...';
      case AppMode.DEVELOPER: return 'Running execution trace...';
      default: return 'Nexus is thinking...';
    }
  };

  const renderComplexityIndicator = (report: any) => {
    const rating = report.complexity_rating;
    let color = 'bg-slate-700';
    let glow = '';
    let width = 'w-0';
    let textColor = 'text-slate-400';
    let label = 'Unknown';
    let icon = '⚪';

    if (rating === 'Low') {
      color = 'bg-emerald-500';
      width = 'w-1/3';
      textColor = 'text-emerald-400';
      label = 'Optimized';
      icon = '✅';
    } else if (rating === 'Medium') {
      color = 'bg-amber-500';
      width = 'w-2/3';
      textColor = 'text-amber-400';
      label = 'Moderate';
      icon = '⚠️';
    } else if (rating === 'High') {
      color = 'bg-rose-600';
      glow = 'shadow-[0_0_15px_rgba(225,29,72,0.6)]';
      width = 'w-full';
      textColor = 'text-rose-400';
      label = 'High Complexity';
      icon = '🔥';
    }

    return (
      <div className="mt-4 p-4 bg-slate-950/80 rounded-2xl border border-slate-800/80 shadow-xl ring-1 ring-white/5 overflow-hidden relative">
        <div className="absolute top-0 right-0 p-3 opacity-10">
          <Icons.Code />
        </div>

        <div className="flex justify-between items-end mb-3">
          <div className="space-y-0.5">
            <span className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] block">Structural Integrity</span>
            <div className="flex items-center gap-2">
              <span className="text-base">{icon}</span>
              <span className={`text-sm font-black uppercase tracking-tight ${textColor}`}>{label}</span>
            </div>
          </div>
          <div className="text-right">
             <span className="text-[10px] font-mono font-bold text-slate-400 uppercase">{report.detected_language} • {report.line_count} Lines</span>
          </div>
        </div>

        <div className="h-2 w-full bg-slate-900 rounded-full overflow-hidden mb-4 border border-white/5">
          <div className={`h-full ${color} ${width} ${glow} transition-all duration-1000 ease-out relative`}>
             <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[shimmer_2s_infinite]" />
          </div>
        </div>

        <div className="flex flex-wrap gap-2">
          {report.features && Object.entries(report.features).map(([feature, enabled]) => (
            <div 
              key={feature} 
              className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg border text-[9px] font-bold uppercase tracking-wider transition-all ${
                enabled 
                  ? 'bg-indigo-500/10 border-indigo-500/30 text-indigo-300' 
                  : 'bg-slate-900/50 border-slate-800 text-slate-600 opacity-50'
              }`}
            >
              <div className={`w-1 h-1 rounded-full ${enabled ? 'bg-indigo-400 shadow-[0_0_5px_rgba(129,140,248,0.8)]' : 'bg-slate-700'}`} />
              {feature.replace('_', ' ')}
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-x border-slate-800 shadow-2xl overflow-hidden relative">
      {/* Header */}
      <div className="z-30 bg-slate-900/80 backdrop-blur-xl border-b border-slate-800 sticky top-0">
        <div className="p-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <button 
              onClick={onMenuToggle}
              className="lg:hidden p-2 hover:bg-slate-800 rounded-xl transition-colors text-slate-400 hover:text-white"
              title="Open Navigation"
            >
              <Icons.Menu />
            </button>
            <div className="flex items-center gap-2.5">
              <div className="p-1.5 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg shadow-lg">
                <Icons.Robot />
              </div>
              <div>
                <h1 className="font-bold text-base tracking-tight text-white leading-none">AI Nexus</h1>
                <span className={`text-[9px] font-bold uppercase tracking-widest ${getModeColor(mode).split(' ')[0]}`}>
                  {mode}
                </span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-800/50 rounded-full border border-slate-700/50 shadow-[0_0_15px_rgba(0,0,0,0.2)]">
               <span className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-indigo-500 animate-pulse shadow-[0_0_8px_rgba(99,102,241,0.5)]' : 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]'}`} />
               <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{isLoading ? 'Busy' : 'Live'}</span>
             </div>
          </div>
        </div>

        {/* Flash UI News Tabs */}
        {mode === AppMode.NEWS && (
          <div className="px-4 py-3 overflow-x-auto scrollbar-hide bg-slate-950/20">
            <div className="flex gap-3 min-w-max pb-1">
              {NEWS_CATEGORIES.map((cat) => (
                <button
                  key={cat.id}
                  onClick={() => handleNewsTabClick(cat.id)}
                  disabled={isLoading}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl text-[11px] font-black transition-all relative overflow-hidden group border-2 ${
                    activeNewsTab === cat.id
                      ? 'bg-amber-400/5 border-amber-400/40 text-amber-400 shadow-[0_0_20px_rgba(251,191,36,0.15)] ring-1 ring-amber-400/20'
                      : 'bg-slate-900/40 border-slate-800/80 text-slate-500 hover:text-slate-300 hover:bg-slate-800/80 hover:border-slate-700'
                  } ${isLoading ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
                >
                  <span className={`text-sm transition-transform duration-300 ${activeNewsTab === cat.id ? 'scale-125' : 'group-hover:scale-110'}`}>{cat.icon}</span>
                  <span className="uppercase tracking-[0.15em]">{cat.label}</span>

                  {activeNewsTab === cat.id && (
                    <>
                      <div className="absolute bottom-0 left-0 right-0 h-[3px] bg-amber-400 shadow-[0_0_10px_rgba(251,191,36,0.8)] animate-in slide-in-from-bottom-1 duration-300" />
                      <div className="absolute top-0 left-0 right-0 h-full bg-gradient-to-t from-amber-400/[0.05] to-transparent" />
                    </>
                  )}
                  <div className="absolute inset-0 bg-white/[0.02] opacity-0 group-hover:opacity-100 transition-opacity" />
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-slate-950"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-6 text-center px-8">
            <div className="p-8 bg-slate-900/50 rounded-[2rem] border border-slate-800/50 animate-pulse shadow-2xl relative">
               <Icons.Robot />
               <div className="absolute inset-0 bg-indigo-500/10 blur-[80px] -z-10 rounded-full" />
            </div>
            <div className="max-w-md">
              <p className="text-3xl font-black text-white mb-2 tracking-tighter">System Online</p>
              <p className="text-sm leading-relaxed text-slate-400 font-bold uppercase tracking-widest opacity-60">
                Connected to <span className="text-indigo-400">{mode}</span> nexus
              </p>
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
          >
            <div className={`max-w-[88%] rounded-[1.75rem] p-5 shadow-2xl border ${
              msg.role === MessageRole.USER 
                ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                : 'bg-slate-800/80 backdrop-blur-md text-slate-100 border-slate-700/50 rounded-tl-none'
            }`}>
              {/* Thinking Segment */}
              {msg.thinking && (
                <div className="mb-4 p-4 bg-black/50 rounded-2xl border border-slate-700/50 text-[11px] text-slate-300 font-mono overflow-hidden shadow-inner ring-1 ring-white/5">
                  <div className="flex items-center gap-2 mb-3 text-indigo-400 border-b border-slate-800/80 pb-2">
                    <Icons.Terminal />
                    <span className="uppercase tracking-tighter font-black text-[10px]">Model Reasoning</span>
                  </div>
                  <div className="opacity-80 italic leading-relaxed">
                    {msg.thinking}
                  </div>
                </div>
              )}

              <div className="whitespace-pre-wrap text-[15px] leading-relaxed mb-1 font-medium tracking-tight">
                {msg.text}
              </div>

              {/* Tool Execution Logs */}
              {(msg.functionCalls && msg.functionCalls.length > 0) && (
                <div className="mt-5 pt-4 border-t border-slate-700/50 space-y-3">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Execution Trace</p>
                  {msg.functionCalls.map((fc, i) => {
                    const response = msg.toolResponses?.find(tr => tr.name === fc.name || tr.id === fc.id)?.response;
                    const report = response?.analysis_report;

                    return (
                      <div key={i} className="space-y-3 animate-in fade-in slide-in-from-left-2">
                        <div className="flex items-center gap-2 text-[11px] font-mono text-cyan-400 bg-cyan-950/30 p-3 rounded-2xl border border-cyan-500/20 shadow-lg">
                          <div className="w-2 h-2 rounded-full bg-cyan-500 animate-pulse shadow-[0_0_12px_rgba(34,211,238,0.8)]" />
                          <span className="tracking-tight">CALL: <span className="font-bold underline decoration-cyan-500/50">{fc.name}</span></span>
                        </div>
                        {fc.name === 'analyze_code_structure' && report && (
                          <div className="animate-in fade-in zoom-in-95 duration-500">
                             {renderComplexityIndicator(report)}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Grounding Links */}
              {msg.groundingLinks && msg.groundingLinks.length > 0 && (
                <div className="mt-5 pt-4 border-t border-slate-700 space-y-3">
                  <div className="flex items-center gap-2 mb-1">
                    <Icons.Search />
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Source Verification</p>
                  </div>
                  <div className="flex flex-wrap gap-2.5">
                    {msg.groundingLinks.map((link, i) => (
                      <a 
                        key={i}
                        href={link.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="group flex items-center gap-2.5 px-4 py-2.5 bg-slate-900/95 border border-slate-700 hover:border-indigo-500/50 rounded-2xl text-[12px] text-indigo-400 hover:text-indigo-300 transition-all shadow-xl active:scale-95"
                      >
                        <Icons.External />
                        <span className="truncate max-w-[180px] font-black uppercase tracking-tighter">{link.title}</span>
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start animate-in fade-in duration-500 translate-y-2">
            <div className="bg-slate-800/90 backdrop-blur-2xl border border-slate-700/50 rounded-[1.75rem] rounded-tl-none p-5 flex gap-4 items-center shadow-2xl ring-1 ring-white/5">
              <div className="flex gap-1.5">
                <span className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                <span className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                <span className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce"></span>
              </div>
              <div className="flex flex-col">
                <span className="text-[12px] font-black text-indigo-400 uppercase tracking-[0.1em] animate-pulse">
                  {getLoadingText(mode)}
                </span>
                <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">
                  Neural Bridge v3.1
                </span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input Area */}
      <form onSubmit={handleSubmit} className="p-6 bg-slate-900/95 border-t border-slate-800 backdrop-blur-3xl z-20">
        <div className="relative group max-w-4xl mx-auto">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder={isLoading ? "Neural synthesis in progress..." : `Command Nexus (${mode})...`}
            disabled={isLoading}
            className="w-full bg-slate-950 border-2 border-slate-800 focus:border-indigo-500/50 focus:ring-0 rounded-2xl px-6 py-5 pr-16 text-[15px] transition-all outline-none disabled:opacity-50 shadow-2xl font-bold placeholder:text-slate-700 placeholder:uppercase placeholder:tracking-widest"
          />
          <button
            type="submit"
            disabled={!input.trim() || isLoading}
            className="absolute right-3 top-1/2 -translate-y-1/2 p-3.5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 text-white rounded-xl transition-all shadow-xl shadow-indigo-600/30 active:scale-90"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
          </button>
        </div>
        <div className="flex justify-between items-center mt-4 px-1 max-w-4xl mx-auto">
          <p className="text-[9px] text-slate-700 uppercase tracking-[0.25em] font-black">
            Powered by Gemini Advanced Architecture
          </p>
          <div className="flex gap-2">
             <div className="w-2 h-1 rounded-full bg-indigo-500/10" />
             <div className="w-4 h-1 rounded-full bg-indigo-500/30" />
             <div className="w-2 h-1 rounded-full bg-indigo-500/10" />
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { ChatInterface } from './components/ChatInterface';
import { SidebarNavigation } from './components/SidebarNavigation';
import { AboutPage } from './components/AboutPage';
import { ChatMessage, MessageRole, AppMode, CustomTool } from './types';
import { GeminiService } from './services/geminiService';
import { Icons } from './constants';

const App: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [mode, setMode] = useState<AppMode>(AppMode.GENERAL);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [customTools, setCustomTools] = useState<CustomTool[]>(() => {
    const saved = localStorage.getItem('nexus_custom_tools');
    return saved ? JSON.parse(saved) : [];
  });

  const gemini = useMemo(() => new GeminiService(), []);

  useEffect(() => {
    localStorage.setItem('nexus_custom_tools', JSON.stringify(customTools));
  }, [customTools]);

  const handleSend = useCallback(async (text: string) => {
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);

    try {
      const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
      }));

      const response = await gemini.sendMessage(text, history, mode, customTools);

      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: response.text || "I'm sorry, I couldn't process that.",
        timestamp: Date.now(),
        functionCalls: response.functionCalls,
        toolResponses: response.toolResponses,
        groundingLinks: response.groundingLinks,
        thinking: response.thinking
      };

      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, {
        id: 'error',
        role: MessageRole.MODEL,
        text: "Error: I encountered a problem connecting to the brain center.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
    }
  }, [messages, mode, gemini, customTools]);

  const handleRefreshNews = useCallback((category?: string) => {
    const topic = category ? `${category} news` : "global news stories across technology, world politics, and science";
    handleSend(`Perform a deep real-time scan of ${topic}. Provide a fresh briefing on the most important stories from the last 24 hours.`);
  }, [handleSend]);

  const changeMode = (newMode: AppMode) => {
    setMode(newMode);
    setIsSidebarOpen(false);
    setIsAboutOpen(false);
    const systemMsg: ChatMessage = {
      id: `sys-${Date.now()}`,
      role: MessageRole.MODEL,
      text: `Switching to ${newMode.toUpperCase()} mode. How can I help you in this context?`,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, systemMsg]);
  };

  const addCustomTool = (tool: CustomTool) => {
    setCustomTools(prev => [...prev, tool]);
  };

  const removeCustomTool = (id: string) => {
    setCustomTools(prev => prev.filter(t => t.id !== id));
  };

  return (
    <div className="flex h-screen bg-slate-950 text-slate-100 overflow-hidden font-sans relative">
      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 z-50 flex lg:hidden">
          <div 
            className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300"
            onClick={() => setIsSidebarOpen(false)}
          />
          <div className="relative z-10 h-full animate-in slide-in-from-left duration-300">
            <SidebarNavigation 
              currentMode={mode}
              onModeChange={changeMode}
              onSend={(text) => {
                handleSend(text);
                setIsSidebarOpen(false);
              }}
              customTools={customTools}
              onAddTool={addCustomTool}
              onRemoveTool={removeCustomTool}
              onOpenAbout={() => { setIsAboutOpen(true); setIsSidebarOpen(false); }}
            />
          </div>
        </div>
      )}

      {/* Desktop Sidebar - Always Visible */}
      <div className="hidden lg:flex shrink-0">
        <SidebarNavigation 
          currentMode={mode}
          onModeChange={changeMode}
          onSend={handleSend}
          customTools={customTools}
          onAddTool={addCustomTool}
          onRemoveTool={removeCustomTool}
          onOpenAbout={() => setIsAboutOpen(true)}
        />
      </div>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 relative">
        <div className="flex-1 flex flex-col max-w-5xl mx-auto w-full relative">
          {isAboutOpen ? (
            <AboutPage onClose={() => setIsAboutOpen(false)} />
          ) : (
            <ChatInterface 
              messages={messages} 
              onSend={handleSend} 
              isLoading={isLoading} 
              mode={mode} 
              onRefresh={mode === AppMode.NEWS ? handleRefreshNews : undefined}
              onMenuToggle={() => setIsSidebarOpen(true)}
            />
          )}
        </div>
      </main>

      {/* Developer Panel - Only shown in DEV mode and large screens */}
      {mode === AppMode.DEVELOPER && !isAboutOpen && (
        <aside className="w-80 border-l border-slate-800 bg-slate-950/50 backdrop-blur-md p-6 overflow-y-auto hidden 2xl:block animate-in slide-in-from-right duration-500">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-6">Execution Log</h2>
          <div className="space-y-8">
            <section>
              <h3 className="text-sm font-semibold mb-3 flex items-center gap-2 text-indigo-400">
                <Icons.Code /> Live Environment
              </h3>
              <div className="space-y-2">
                {['get_random_joke', 'get_weather', 'get_learning_resource', 'analyze_code_structure'].map(t => (
                  <div key={t} className="flex items-center gap-2 px-2 py-1 bg-slate-900/50 rounded font-mono text-[9px] text-slate-400 border border-slate-800/50">
                    <div className="w-1 h-1 bg-green-500/50 rounded-full" />
                    {t}
                  </div>
                ))}
              </div>
            </section>
          </div>
        </aside>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
