                                src={imageUrl} 
                                alt={response?.revised_prompt || "Generated Content"} 
                                className="w-full h-auto rounded-2xl shadow-lg hover:scale-[1.02] transition-transform duration-500 cursor-zoom-in"
                                onClick={() => window.open(imageUrl)}
                             />
                             <div className="mt-3 px-3 py-2">
                                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mb-1 flex justify-between items-center">
                                  <span>Visual Hash Captured</span>
                                  <span className="text-indigo-400/50 italic font-mono">nexus_v2.5_flash</span>
                                </p>
                             </div>
                          </div>
                        )}

                        {/* Collapsible Tool Response */}
                        {isExpanded && response && (
                          <div className="animate-in slide-in-from-top-2 fade-in duration-300">
                             <div className="bg-black/40 border border-cyan-900/30 rounded-2xl p-4 font-mono text-[10px] text-cyan-200/80 overflow-x-auto whitespace-pre">
                               {/* Mask huge base64 strings in the JSON details view for performance and readability */}
                               {JSON.stringify(
