                        {fc.name === 'analyze_code_structure' && report && (
                          <div className="animate-in fade-in zoom-in-95 duration-500">
                             {renderComplexityIndicator(report)}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Grounding Links */}
              {msg.groundingLinks && msg.groundingLinks.length > 0 && (
                <div className="mt-5 pt-4 border-t border-slate-700 space-y-3">
                  <div className="flex items-center gap-2 mb-1">
                    <Icons.Search />
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Source Verification</p>
                  </div>
                  <div className="flex flex-wrap gap-2.5">
                    {msg.groundingLinks.map((link, i) => (
                      <a 
                        key={i}
                        href={link.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="group flex items-center gap-2.5 px-4 py-2.5 bg-slate-900/95 border border-slate-700 hover:border-indigo-500/50 rounded-2xl text-[12px] text-indigo-400 hover:text-indigo-300 transition-all shadow-xl active:scale-95"
                      >
                        <Icons.External />
                        <span className="truncate max-w-[180px] font-black uppercase tracking-tighter">{link.title}</span>
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start animate-in fade-in duration-500 translate-y-2">
            <div className="bg-slate-800/90 backdrop-blur-2xl border border-slate-700/50 rounded-[1.75rem] rounded-tl-none p-5 flex gap-4 items-center shadow-2xl ring-1 ring-white/5">
              <div className="flex gap-1.5">
                <span className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                <span className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                <span className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-bounce"></span>
              </div>
              <div className="flex flex-col">
                <span className="text-[12px] font-black text-indigo-400 uppercase tracking-[0.1em] animate-pulse">
                  {getLoadingText(mode)}
                </span>
                <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">
                  Neural Bridge v3.1
                </span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input Area */}
      <form onSubmit={handleSubmit} className="p-6 bg-slate-900/95 border-t border-slate-800 backdrop-blur-3xl z-20">
        <div className="relative group max-w-4xl mx-auto flex gap-2">
          <div className="relative flex-1">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder={isLoading ? "Neural synthesis in progress..." : `Command Nexus (${mode})...`}
              disabled={isLoading}
              className="w-full bg-slate-950 border-2 border-slate-800 focus:border-indigo-500/50 focus:ring-0 rounded-2xl px-6 py-5 pr-12 text-[15px] transition-all outline-none disabled:opacity-50 shadow-2xl font-bold placeholder:text-slate-700 placeholder:uppercase placeholder:tracking-widest"
            />
            <div className="absolute right-3 top-1/2 -translate-y-1/2 flex gap-1">
               <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="p-2 text-slate-500 hover:text-indigo-400 transition-colors rounded-lg hover:bg-slate-800"
                  title="Upload Custom Icon"
                >
                  <Icons.Image />
                </button>
            </div>
          </div>
          <button
            type="submit"
            disabled={!input.trim() || isLoading}
            className="p-5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 text-white rounded-2xl transition-all shadow-xl shadow-indigo-600/30 active:scale-90 flex items-center justify-center min-w-[64px]"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
          </button>
        </div>
        <div className="flex justify-between items-center mt-4 px-1 max-w-4xl mx-auto">
          <p className="text-[9px] text-slate-700 uppercase tracking-[0.25em] font-black">
            Powered by Gemini Advanced Architecture
          </p>
          <div className="flex gap-2">
             <div className="w-2 h-1 rounded-full bg-indigo-500/10" />
             <div className="w-4 h-1 rounded-full bg-indigo-500/30" />
             <div className="w-2 h-1 rounded-full bg-indigo-500/10" />
          </div>
        </div>
      </form>
    </div>
  );
};

